/* ─────────────────────────────────────────────
   GreenBean Coffee — Shared Design System
   Colors: OKLCH perceptual color space
───────────────────────────────────────────── */

:root {
  /* Brand Colors */
  --green-primary:    oklch(48% 0.15 148);   /* #00824A */
  --green-hover:      oklch(42% 0.14 148);
  --green-light:      oklch(92% 0.05 148);
  --forest-dark:      oklch(28% 0.08 148);   /* #32462F */
  --cream-light:      oklch(92% 0.06 80);    /* #F3CEA1 */
  --cream-bg:         oklch(97% 0.02 80);

  /* Text */
  --text-primary:     oklch(20% 0.04 148);
  --text-muted:       oklch(45% 0.04 148);
  --text-light:       oklch(65% 0.03 148);

  /* Surfaces */
  --surface-white:    oklch(100% 0 0);
  --surface-warm:     oklch(98% 0.01 80);
  --border-light:     oklch(90% 0.02 80);

  /* Shadows */
  --shadow-sm:  0 1px 3px oklch(20% 0.05 148 / 0.08), 0 1px 2px oklch(20% 0.05 148 / 0.06);
  --shadow-md:  0 4px 12px oklch(20% 0.05 148 / 0.10), 0 2px 4px oklch(20% 0.05 148 / 0.06);
  --shadow-lg:  0 10px 32px oklch(20% 0.05 148 / 0.12), 0 4px 8px oklch(20% 0.05 148 / 0.06);

  /* Spacing scale */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;

  /* Typography */
  --font-body: 'DM Sans', system-ui, sans-serif;
  --font-display: 'DM Serif Display', Georgia, serif;

  /* Radii */
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-xl: 28px;
  --radius-full: 999px;
}

/* ── Reset & Base ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  color: var(--text-primary);
  background: var(--surface-white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a { text-decoration: none; color: inherit; }
ul { list-style: none; }
img { max-width: 100%; height: auto; display: block; }
button { cursor: pointer; font-family: inherit; border: none; }

/* ── Typography ── */
h1, h2, h3, h4, h5 {
  font-family: var(--font-display);
  color: var(--forest-dark);
  line-height: 1.2;
}
h1 { font-size: clamp(2rem, 4vw, 3.2rem); }
h2 { font-size: clamp(1.6rem, 3vw, 2.4rem); }
h3 { font-size: clamp(1.2rem, 2vw, 1.6rem); }

.section-title {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  color: var(--forest-dark);
  margin-bottom: var(--space-6);
}

/* ── Buttons ── */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--green-primary);
  color: #fff;
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 0.95rem;
  padding: 12px 24px;
  border-radius: var(--radius-full);
  border: 2px solid var(--green-primary);
  transition: background 0.2s, transform 0.15s, box-shadow 0.2s;
  white-space: nowrap;
}
.btn-primary:hover {
  background: var(--green-hover);
  border-color: var(--green-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}
.btn-primary:active { transform: translateY(0); }

.btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  color: var(--text-primary);
  font-family: var(--font-body);
  font-weight: 500;
  font-size: 0.95rem;
  padding: 10px 20px;
  border-radius: var(--radius-full);
  border: 2px solid var(--border-light);
  transition: border-color 0.2s, background 0.2s;
}
.btn-ghost:hover { border-color: var(--green-primary); color: var(--green-primary); }

.btn-outline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  color: #fff;
  font-family: var(--font-body);
  font-weight: 600;
  font-size: 0.9rem;
  padding: 10px 22px;
  border-radius: var(--radius-full);
  border: 2px solid rgba(255,255,255,0.7);
  transition: background 0.2s, border-color 0.2s;
}
.btn-outline:hover { background: rgba(255,255,255,0.15); border-color: #fff; }

.btn-cream {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: var(--cream-light);
  color: var(--forest-dark);
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 0.95rem;
  padding: 12px 24px;
  border-radius: var(--radius-full);
  border: none;
  transition: background 0.2s, transform 0.15s;
}
.btn-cream:hover { background: oklch(88% 0.07 80); transform: translateY(-1px); }

.btn-lg { padding: 16px 36px; font-size: 1.05rem; }
.btn-sm { padding: 8px 18px; font-size: 0.88rem; }

/* ── Cookie Banner ── */
.cookie-banner {
  position: fixed;
  bottom: 0; left: 0; right: 0;
  z-index: 1000;
  background: var(--forest-dark);
  color: #fff;
  padding: 20px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  box-shadow: 0 -4px 20px oklch(20% 0.05 148 / 0.2);
  flex-wrap: wrap;
}
.cookie-content { display: flex; align-items: flex-start; gap: 16px; flex: 1; min-width: 240px; }
.cookie-icon { font-size: 2rem; flex-shrink: 0; }
.cookie-text strong { display: block; margin-bottom: 4px; font-size: 1rem; }
.cookie-text p { font-size: 0.85rem; opacity: 0.8; line-height: 1.5; }
.cookie-actions { display: flex; gap: 12px; flex-shrink: 0; }
.cookie-actions .btn-ghost { color: #fff; border-color: rgba(255,255,255,0.4); font-size: 0.88rem; }
.cookie-actions .btn-ghost:hover { border-color: #fff; color: #fff; background: rgba(255,255,255,0.1); }
.cookie-actions .btn-primary { font-size: 0.88rem; }

/* ── Site Header ── */
.site-header {
  position: sticky;
  top: 0;
  z-index: 900;
  background: var(--surface-white);
  border-bottom: 1px solid var(--border-light);
  box-shadow: var(--shadow-sm);
}
.header-inner {
  display: flex;
  align-items: center;
  gap: 32px;
  padding: 0 48px;
  height: 72px;
  max-width: 1300px;
  margin: 0 auto;
}
.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
  text-decoration: none;
}
.logo-mark {
  width: 40px; height: 40px;
  background: var(--green-primary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 700;
}
.logo-mark-lg { width: 52px; height: 52px; font-size: 1.8rem; }
.logo-text {
  font-family: var(--font-display);
  font-size: 1.2rem;
  color: var(--forest-dark);
}
.main-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}
.nav-link {
  font-weight: 500;
  font-size: 0.95rem;
  color: var(--text-primary);
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  transition: color 0.15s, background 0.15s;
}
.nav-link:hover, .nav-link.active { color: var(--green-primary); background: var(--green-light); }
.header-actions { display: flex; gap: 10px; align-items: center; margin-left: auto; }

/* Mobile nav */
.mobile-menu-btn {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  padding: 8px;
  margin-left: auto;
}
.mobile-menu-btn span {
  display: block;
  width: 24px; height: 2px;
  background: var(--text-primary);
  border-radius: 2px;
  transition: transform 0.2s;
}
.mobile-nav {
  display: none;
  flex-direction: column;
  padding: 16px 24px 24px;
  border-top: 1px solid var(--border-light);
  background: var(--surface-white);
}
.mobile-nav.open { display: flex; }
.mobile-nav-link {
  font-weight: 500;
  font-size: 1.05rem;
  color: var(--text-primary);
  padding: 14px 0;
  border-bottom: 1px solid var(--border-light);
}
.mobile-nav-actions { display: flex; gap: 12px; margin-top: 20px; }

/* ── Footer ── */
.site-footer {
  background: var(--forest-dark);
  color: oklch(80% 0.04 148);
  padding: 60px 0 0;
  margin-top: 80px;
}
.footer-inner { max-width: 1300px; margin: 0 auto; padding: 0 48px; }
.footer-logo {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 48px;
  flex-wrap: wrap;
}
.footer-logo .logo-text { color: var(--cream-light); font-size: 1.3rem; }
.footer-tagline { font-size: 0.85rem; color: oklch(65% 0.04 148); margin-left: auto; font-style: italic; }
.footer-columns {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 32px;
  padding-bottom: 48px;
  border-bottom: 1px solid oklch(38% 0.05 148);
}
.footer-heading {
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 0.9rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--cream-light);
  margin-bottom: 16px;
  cursor: default;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.accordion-icon { display: none; }
.footer-links li { margin-bottom: 10px; }
.footer-links a {
  font-size: 0.9rem;
  color: oklch(72% 0.04 148);
  transition: color 0.15s;
}
.footer-links a:hover { color: var(--cream-light); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 0;
  font-size: 0.85rem;
  color: oklch(55% 0.04 148);
}
.footer-social { display: flex; gap: 16px; }
.social-link { font-size: 1.2rem; transition: transform 0.15s; }
.social-link:hover { transform: scale(1.2); }

/* ── Page Hero (interior pages) ── */
.page-hero {
  background: linear-gradient(135deg, var(--forest-dark) 0%, oklch(32% 0.09 148) 100%);
  padding: 80px 48px;
  text-align: center;
  color: #fff;
}
.page-hero h1 { color: var(--cream-light); font-size: clamp(2rem, 4vw, 3rem); margin-bottom: 16px; }
.page-hero p { font-family: var(--font-body); font-size: 1.1rem; opacity: 0.85; max-width: 600px; margin: 0 auto 28px; }

/* ── Chip / Badge ── */
.badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: var(--green-light);
  color: var(--green-primary);
  font-size: 0.8rem;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: var(--radius-full);
}

/* ── Utility ── */
.container { max-width: 1200px; margin: 0 auto; padding: 0 48px; }
.container-sm { max-width: 860px; margin: 0 auto; padding: 0 48px; }
.text-center { text-align: center; }
.mt-8 { margin-top: 32px; }
.mb-8 { margin-bottom: 32px; }
.gap-4 { gap: 16px; }
.flex { display: flex; }
.flex-wrap { flex-wrap: wrap; }

/* ── Responsive ── */
@media (max-width: 1024px) {
  .footer-columns { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 768px) {
  .header-inner { padding: 0 20px; gap: 16px; }
  .main-nav { display: none; }
  .header-actions { display: none; }
  .mobile-menu-btn { display: flex; }
  .container, .container-sm { padding: 0 20px; }
  .footer-inner { padding: 0 20px; }
  .footer-columns { grid-template-columns: 1fr; gap: 0; }
  .footer-heading {
    cursor: pointer;
    padding: 16px 0;
    margin-bottom: 0;
    border-bottom: 1px solid oklch(38% 0.05 148);
  }
  .accordion-icon { display: block; font-style: normal; font-size: 1.2rem; }
  .footer-links { display: none; padding: 12px 0 16px; }
  .footer-links.open { display: block; }
  .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
  .page-hero { padding: 60px 20px; }
}

