<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700;1,9..40,400&family=DM+Serif+Display:ital@0;1&display=swap" rel="stylesheet">
<link rel="stylesheet" href="shared.css">
<style>
  /* ── Rewards Hero ── */
  .rewards-hero {
    background: linear-gradient(135deg, oklch(28% 0.08 148) 0%, oklch(22% 0.06 148) 50%, oklch(18% 0.05 148) 100%);
    padding: 100px 48px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .rewards-hero::before {
    content: '';
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse at 50% 0%, oklch(55% 0.18 140 / 0.12) 0%, transparent 65%);
  }
  .rewards-hero-content { position: relative; z-index: 1; max-width: 680px; margin: 0 auto; }
  .rewards-hero h1 { color: var(--cream-light); font-size: clamp(2.2rem, 4vw, 3.5rem); margin-bottom: 20px; }
  .rewards-hero p { font-family: var(--font-body); font-size: 1.1rem; color: oklch(80% 0.05 148); margin-bottom: 36px; line-height: 1.6; }
  .rewards-hero-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }
  .star-decoration {
    position: absolute;
    font-size: 2rem;
    opacity: 0.12;
    animation: float 6s ease-in-out infinite;
  }
  @keyframes float { 0%,100%{transform:translateY(0)} 50%{transform:translateY(-12px)} }

  /* ── How It Works ── */
  .how-it-works { padding: 80px 48px; background: var(--surface-warm); }
  .how-it-works-inner { max-width: 900px; margin: 0 auto; text-align: center; }
  .hiw-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; margin-top: 48px; }
  .hiw-step { display: flex; flex-direction: column; align-items: center; gap: 16px; }
  .hiw-icon {
    width: 72px; height: 72px;
    background: var(--green-primary);
    border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    font-size: 2rem;
    box-shadow: 0 4px 20px oklch(48% 0.15 148 / 0.3);
  }
  .hiw-step h3 {
    font-family: var(--font-body);
    font-size: 1rem;
    font-weight: 700;
    color: var(--forest-dark);
  }
  .hiw-step p { font-size: 0.9rem; color: var(--text-muted); line-height: 1.6; text-align: center; }
  .hiw-connector { display: flex; align-items: center; justify-content: center; padding-top: 36px; }
  .hiw-connector svg { opacity: 0.3; }

  /* ── Status Tiers ── */
  .status-tiers { padding: 80px 48px; }
  .status-tiers-inner { max-width: 1100px; margin: 0 auto; }
  .tiers-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 48px; }
  .tier-card {
    border-radius: 24px;
    overflow: hidden;
    box-shadow: var(--shadow-md);
    transition: transform 0.25s, box-shadow 0.25s;
  }
  .tier-card:hover { transform: translateY(-6px); box-shadow: var(--shadow-lg); }
  .tier-card-header { padding: 32px 28px 24px; text-align: center; }
  .tier-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    padding: 5px 14px;
    border-radius: var(--radius-full);
    margin-bottom: 12px;
  }
  .tier-card.green-tier .tier-card-header { background: linear-gradient(135deg, oklch(55% 0.18 148) 0%, oklch(45% 0.16 148) 100%); }
  .tier-card.green-tier .tier-badge { background: rgba(255,255,255,0.2); color: #fff; }
  .tier-card.gold-tier .tier-card-header { background: linear-gradient(135deg, oklch(62% 0.18 65) 0%, oklch(52% 0.16 55) 100%); }
  .tier-card.gold-tier .tier-badge { background: rgba(255,255,255,0.2); color: #fff; }
  .tier-card.reserve-tier .tier-card-header { background: linear-gradient(135deg, oklch(42% 0.10 280) 0%, oklch(32% 0.08 280) 100%); }
  .tier-card.reserve-tier .tier-badge { background: rgba(255,255,255,0.2); color: #fff; }
  .tier-name { font-family: var(--font-display); font-size: 2rem; color: #fff; margin-bottom: 4px; }
  .tier-threshold { font-size: 0.9rem; color: rgba(255,255,255,0.8); }
  .tier-card-body { padding: 24px 28px; background: var(--surface-white); border: 1px solid var(--border-light); border-top: none; border-radius: 0 0 24px 24px; }
  .tier-benefit {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    padding: 10px 0;
    border-bottom: 1px solid var(--border-light);
    font-size: 0.9rem;
    color: var(--text-primary);
  }
  .tier-benefit:last-child { border-bottom: none; }
  .tier-benefit-check { color: var(--green-primary); flex-shrink: 0; font-size: 1rem; margin-top: 1px; }

  /* ── Redemption Levels Tabs ── */
  .redemption-section { padding: 80px 48px; background: oklch(97% 0.02 148); }
  .redemption-inner { max-width: 900px; margin: 0 auto; }
  .redemption-section .section-label { text-align: center; }
  .redemption-section .section-title { text-align: center; margin-bottom: 48px; }

  .tabs-container { background: var(--surface-white); border-radius: var(--radius-xl); box-shadow: var(--shadow-md); overflow: hidden; }
  .tabs-nav {
    display: flex;
    overflow-x: auto;
    scrollbar-width: none;
    border-bottom: 2px solid var(--border-light);
    background: var(--surface-warm);
  }
  .tabs-nav::-webkit-scrollbar { display: none; }
  .tab-btn {
    flex: 1;
    min-width: 90px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    padding: 16px 12px;
    background: none;
    border: none;
    border-bottom: 3px solid transparent;
    margin-bottom: -2px;
    cursor: pointer;
    transition: background 0.15s, border-color 0.15s;
    font-family: var(--font-body);
  }
  .tab-btn:hover { background: var(--green-light); }
  .tab-btn.active { border-bottom-color: var(--green-primary); background: var(--surface-white); }
  .tab-stars {
    font-size: 1.1rem;
    font-weight: 800;
    color: var(--forest-dark);
    font-family: var(--font-body);
  }
  .tab-btn.active .tab-stars { color: var(--green-primary); }
  .tab-label { font-size: 0.72rem; font-weight: 500; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.06em; }
  .tab-btn.active .tab-label { color: var(--green-primary); }

  .tab-panels { padding: 40px; }
  .tab-panel { display: none; animation: fadeInUp 0.25s ease; }
  .tab-panel.active { display: flex; gap: 32px; align-items: flex-start; }
  @keyframes fadeInUp {
    from { opacity: 0; transform: translateY(10px); }
    to { opacity: 1; transform: translateY(0); }
  }
  .tab-visual {
    flex-shrink: 0;
    width: 140px;
    height: 140px;
    border-radius: 50%;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 4px;
    background: linear-gradient(135deg, var(--green-primary) 0%, oklch(42% 0.12 148) 100%);
    box-shadow: 0 6px 24px oklch(48% 0.15 148 / 0.3);
  }
  .tab-visual .stars-count { font-size: 2rem; font-weight: 900; color: #fff; font-family: var(--font-body); line-height: 1; }
  .tab-visual .stars-label { font-size: 0.75rem; color: rgba(255,255,255,0.8); font-weight: 500; }
  .tab-visual .stars-icon { font-size: 1.6rem; }
  .tab-info { flex: 1; }
  .tab-info h3 { font-size: 1.5rem; margin-bottom: 8px; }
  .tab-info .value-tag {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: oklch(92% 0.08 80);
    color: oklch(42% 0.12 60);
    font-size: 0.85rem;
    font-weight: 600;
    padding: 4px 12px;
    border-radius: var(--radius-full);
    margin-bottom: 16px;
  }
  .tab-info p { font-size: 0.95rem; color: var(--text-muted); line-height: 1.7; }

  /* ── Partnerships ── */
  .partnerships { padding: 80px 48px; }
  .partnerships-inner { max-width: 900px; margin: 0 auto; }
  .partners-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 40px; }
  .partner-card {
    border: 1px solid var(--border-light);
    border-radius: var(--radius-lg);
    padding: 28px;
    display: flex;
    align-items: flex-start;
    gap: 20px;
    transition: box-shadow 0.2s;
  }
  .partner-card:hover { box-shadow: var(--shadow-md); }
  .partner-logo {
    width: 56px; height: 56px;
    border-radius: var(--radius-md);
    display: flex; align-items: center; justify-content: center;
    font-size: 1.8rem;
    flex-shrink: 0;
  }
  .partner-logo.delta { background: linear-gradient(135deg, oklch(35% 0.08 260) 0%, oklch(25% 0.06 260) 100%); }
  .partner-logo.marriott { background: linear-gradient(135deg, oklch(42% 0.10 15) 0%, oklch(32% 0.08 15) 100%); }
  .partner-info h4 { font-family: var(--font-body); font-weight: 700; margin-bottom: 6px; }
  .partner-info p { font-size: 0.9rem; color: var(--text-muted); line-height: 1.5; }

  /* ── App Download ── */
  .app-download {
    background: linear-gradient(135deg, oklch(28% 0.08 148) 0%, oklch(22% 0.06 148) 100%);
    padding: 80px 48px;
    text-align: center;
  }
  .app-download h2 { color: var(--cream-light); margin-bottom: 16px; }
  .app-download p { color: oklch(75% 0.05 148); font-size: 1rem; max-width: 500px; margin: 0 auto 36px; line-height: 1.6; }
  .app-buttons { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }
  .app-btn {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: #fff;
    color: var(--forest-dark);
    font-family: var(--font-body);
    font-weight: 700;
    font-size: 0.95rem;
    padding: 14px 24px;
    border-radius: var(--radius-md);
    transition: transform 0.15s, box-shadow 0.15s;
    text-decoration: none;
  }
  .app-btn:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
  .app-btn-icon { font-size: 1.4rem; }

  /* ── Terms ── */
  .terms-section {
    padding: 32px 48px;
    border-top: 1px solid var(--border-light);
    text-align: center;
  }
  .terms-section p { font-size: 0.8rem; color: var(--text-light); line-height: 1.6; max-width: 700px; margin: 0 auto; }
  .terms-section a { color: var(--green-primary); text-decoration: underline; }

  @media (max-width: 900px) {
    .hiw-grid { grid-template-columns: 1fr; gap: 24px; }
    .tiers-grid { grid-template-columns: 1fr; }
    .partners-grid { grid-template-columns: 1fr; }
    .tab-panel.active { flex-direction: column; align-items: center; text-align: center; }
    .tab-visual { width: 120px; height: 120px; }
  }
  @media (max-width: 768px) {
    .rewards-hero { padding: 60px 20px; }
    .how-it-works, .status-tiers, .redemption-section, .partnerships, .app-download, .terms-section { padding: 60px 20px; }
    .tab-panels { padding: 24px 20px; }
  }
</style>
</head>
<body>

<!-- Header -->
<header class="site-header">
  <div class="header-inner">
    <a href="index.html" class="logo">
      <div class="logo-mark">G</div>
