<!-- Rewards Hero -->
<section class="rewards-hero">
  <span class="star-decoration" style="top:15%;left:8%;animation-delay:0s">⭐</span>
  <span class="star-decoration" style="top:30%;right:10%;animation-delay:1.5s">✨</span>
  <span class="star-decoration" style="bottom:20%;left:15%;animation-delay:3s">⭐</span>
  <span class="star-decoration" style="bottom:30%;right:20%;animation-delay:2s">✨</span>
  <div class="rewards-hero-content">
    <div class="badge" style="margin-bottom:20px;background:oklch(55% 0.18 140 / 0.2);color:oklch(85% 0.10 140);">⭐ GreenBean Rewards</div>
    <h1>Collect Stars. Get rewarded. Sip happy.</h1>
    <p>Join GreenBean Rewards and earn Stars with every sip. Redeem for free drinks, food, and more — plus enjoy exclusive perks as you level up.</p>
    <div class="rewards-hero-actions">
      <button class="btn-cream btn-lg">Join now — it's free</button>
      <button class="btn-outline btn-lg">Sign in</button>
    </div>
  </div>
</section>

<!-- How It Works -->
<section class="how-it-works">
  <div class="how-it-works-inner">
    <div class="section-label">Getting started</div>
    <h2 class="section-title">How it works</h2>
    <div class="hiw-grid">
      <div class="hiw-step">
        <div class="hiw-icon">☕</div>
        <h3>1. Collect Stars</h3>
        <p>Earn Stars by making eligible purchases and participating in challenges, offers and games.</p>
      </div>
      <div class="hiw-step">
        <div class="hiw-icon">🎁</div>
        <h3>2. Enjoy free treats</h3>
        <p>Redeem your Stars for free food, drinks and more. Look forward to a birthday treat on us every year.</p>
      </div>
      <div class="hiw-step">
        <div class="hiw-icon">🏆</div>
        <h3>3. Unlock benefits</h3>
        <p>Keep earning Stars to increase your status and help you get to free faster. Discover more benefits at every level.</p>
      </div>
    </div>
  </div>
</section>

<!-- Status Tiers -->
<section class="status-tiers">
  <div class="status-tiers-inner">
    <div class="section-label" style="text-align:center">Membership levels</div>
    <h2 class="section-title" style="text-align:center">Your status grows with you</h2>
    <div class="tiers-grid">
      <!-- Green Tier -->
      <div class="tier-card green-tier">
        <div class="tier-card-header">
          <div class="tier-badge">🌿 Entry Level</div>
          <div class="tier-name">Green</div>
          <div class="tier-threshold">Less than 500 ★ per year</div>
        </div>
        <div class="tier-card-body">
          <div class="tier-benefit"><span class="tier-benefit-check">✓</span> Free birthday treat</div>
          <div class="tier-benefit"><span class="tier-benefit-check">✓</span> Earn 1 ★ per $1 spent</div>
          <div class="tier-benefit"><span class="tier-benefit-check">✓</span> Free Mod Mondays</div>
          <div class="tier-benefit"><span class="tier-benefit-check">✓</span> Double Stars with personal cup</div>
        </div>
      </div>
      <!-- Gold Tier -->
      <div class="tier-card gold-tier">
        <div class="tier-card-header">
          <div class="tier-badge">⭐ Popular</div>
          <div class="tier-name">Gold</div>
          <div class="tier-threshold">500+ ★ per year</div>
        </div>
        <div class="tier-card-body">
          <div class="tier-benefit"><span class="tier-benefit-check">✓</span> 7-day birthday window</div>
          <div class="tier-benefit"><span class="tier-benefit-check">✓</span> Earn 1.2 ★ per $1 spent</div>
          <div class="tier-benefit"><span class="tier-benefit-check">✓</span> Stars won't expire</div>
          <div class="tier-benefit"><span class="tier-benefit-check">✓</span> 4 extra Double Star Days</div>
        </div>
      </div>
      <!-- Reserve Tier -->
      <div class="tier-card reserve-tier">
        <div class="tier-card-header">
          <div class="tier-badge">💎 Elite</div>
          <div class="tier-name">Reserve</div>
          <div class="tier-threshold">2,500+ ★ per year</div>
        </div>
        <div class="tier-card-body">
          <div class="tier-benefit"><span class="tier-benefit-check">✓</span> 30-day birthday window</div>
          <div class="tier-benefit"><span class="tier-benefit-check">✓</span> Earn 1.7 ★ per $1 spent</div>
          <div class="tier-benefit"><span class="tier-benefit-check">✓</span> Exclusive global coffee experiences</div>
          <div class="tier-benefit"><span class="tier-benefit-check">✓</span> Free personalized Reserve Card</div>
          <div class="tier-benefit"><span class="tier-benefit-check">✓</span> 6 extra Double Star Days</div>
        </div>
      </div>
    </div>
  </div>
</section>

<!-- Redemption Levels (Tabs) -->
<section class="redemption-section">
  <div class="redemption-inner">
    <div class="section-label">Redeem your Stars</div>
