          <span class="tab-stars">60 ★</span>
          <span class="tab-label">Discount</span>
        </button>
        <button class="tab-btn" role="tab" aria-selected="false" data-tab="100">
          <span class="tab-stars">100 ★</span>
          <span class="tab-label">Brewed</span>
        </button>
        <button class="tab-btn" role="tab" aria-selected="false" data-tab="200">
          <span class="tab-stars">200 ★</span>
          <span class="tab-label">Handcrafted</span>
        </button>
        <button class="tab-btn" role="tab" aria-selected="false" data-tab="300">
          <span class="tab-stars">300 ★</span>
          <span class="tab-label">Sandwich</span>
