<script>
  // ── Featured carousel ──
  function initCarousel(trackId, prevBtnId, nextBtnId, itemsVisible) {
    const track = document.getElementById(trackId);
    const prevBtn = document.getElementById(prevBtnId);
    const nextBtn = document.getElementById(nextBtnId);
    if (!track) return;
    let current = 0;
    const items = track.querySelectorAll('.gift-card-item');
    const total = items.length;
    function getVisible() {
      if (window.innerWidth <= 600) return 1;
      if (window.innerWidth <= 900) return 2;
      return itemsVisible || 4;
    }
    function update() {
      const vis = getVisible();
      const itemW = track.parentElement.offsetWidth / vis;
      track.style.transform = `translateX(-${current * itemW}px)`;
      if (prevBtn) prevBtn.disabled = current === 0;
      if (nextBtn) nextBtn.disabled = current >= total - vis;
    }
    if (prevBtn) prevBtn.addEventListener('click', () => { if (current > 0) { current--; update(); } });
    if (nextBtn) nextBtn.addEventListener('click', () => {
      const vis = getVisible();
      if (current < total - vis) { current++; update(); }
    });
    window.addEventListener('resize', update);
    update();
  }
  initCarousel('featuredTrack', 'featuredPrev', 'featuredNext', 4);

  // ── Mini carousels ──
  document.querySelectorAll('[data-mini-prev]').forEach(btn => {
    btn.addEventListener('click', () => {
      const trackId = btn.dataset.miniPrev;
      shiftMiniCarousel(trackId, -1);
    });
  });
  document.querySelectorAll('[data-mini-next]').forEach(btn => {
    btn.addEventListener('click', () => {
      const trackId = btn.dataset.miniNext;
      shiftMiniCarousel(trackId, 1);
    });
  });
  const miniCarouselState = {};
  function shiftMiniCarousel(trackId, dir) {
    const track = document.getElementById(trackId);
    if (!track) return;
    const items = track.querySelectorAll('.mini-card');
    const total = items.length;
    if (!miniCarouselState[trackId]) miniCarouselState[trackId] = 0;
    miniCarouselState[trackId] = Math.max(0, Math.min(total - 2, miniCarouselState[trackId] + dir));
    const itemW = track.parentElement.offsetWidth / 2 + 6;
    track.style.transform = `translateX(-${miniCarouselState[trackId] * itemW}px)`;
    track.style.transition = 'transform 0.3s ease';
  }

  // ── Quick link chips ──
  document.querySelectorAll('.quick-link-chip').forEach(chip => {
    chip.addEventListener('click', () => {
      document.querySelectorAll('.quick-link-chip').forEach(c => c.classList.remove('active'));
      chip.classList.add('active');
    });
  });

  // ── FAQ ──
  function toggleFaq(btn) {
    const item = btn.closest('.faq-item');
    const wasOpen = item.classList.contains('open');
    document.querySelectorAll('.faq-item').forEach(i => i.classList.remove('open'));
    if (!wasOpen) item.classList.add('open');
  }
</script>
