<script src="shared.js"></script>
<script>
  // ── Order type toggle ──
  const pickupBtn = document.getElementById('pickupBtn');
  const deliveryBtn = document.getElementById('deliveryBtn');
  const statusBar = document.getElementById('orderStatusBar');

  pickupBtn.addEventListener('click', () => {
    pickupBtn.classList.add('active');
    deliveryBtn.classList.remove('active');
    statusBar.textContent = '📍 Showing Pickup locations near you';
    statusBar.className = 'order-status-bar';
  });
  deliveryBtn.addEventListener('click', () => {
    deliveryBtn.classList.add('active');
    pickupBtn.classList.remove('active');
    statusBar.textContent = '🚚 Showing Delivery locations — delivery available at select stores';
    statusBar.className = 'order-status-bar delivery';
  });

  // ── Search suggestions ──
  const searchInput = document.getElementById('locationSearch');
  const suggestions = document.getElementById('searchSuggestions');

  searchInput.addEventListener('input', () => {
    if (searchInput.value.trim().length > 1) {
      suggestions.classList.add('visible');
    } else {
      suggestions.classList.remove('visible');
    }
  });
  searchInput.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') suggestions.classList.remove('visible');
  });
  document.addEventListener('click', (e) => {
    if (!searchInput.contains(e.target) && !suggestions.contains(e.target)) {
      suggestions.classList.remove('visible');
    }
  });
  suggestions.querySelectorAll('.suggestion-item').forEach(item => {
    item.addEventListener('click', () => {
      searchInput.value = item.dataset.location;
      suggestions.classList.remove('visible');
    });
  });

  // ── Filter panel toggle ──
  const filterBtn = document.getElementById('filterBtn');
  const filterPanel = document.getElementById('filterPanel');
  const filterCount = document.getElementById('filterCount');
  const activeFiltersEl = document.getElementById('activeFilters');

  filterBtn.addEventListener('click', () => {
    const isOpen = filterPanel.classList.toggle('open');
    filterBtn.classList.toggle('active', isOpen);
    filterBtn.setAttribute('aria-expanded', isOpen);
  });

  filterPanel.querySelectorAll('input[type=checkbox]').forEach(checkbox => {
    checkbox.addEventListener('change', updateFilters);
  });

  function updateFilters() {
    const checked = Array.from(filterPanel.querySelectorAll('input:checked'));
    const count = checked.length;
    filterCount.textContent = count;
    filterCount.style.display = count > 0 ? 'flex' : 'none';

    activeFiltersEl.innerHTML = checked.map(cb => {
      const label = cb.closest('label').textContent.trim();
      return `<span class="active-filter-tag">${label} <button onclick="removeFilter('${cb.dataset.filter}')">×</button></span>`;
    }).join('');
  }

  window.removeFilter = function(filterKey) {
    const checkbox = filterPanel.querySelector(`input[data-filter="${filterKey}"]`);
    if (checkbox) { checkbox.checked = false; updateFilters(); }
  };

  // ── Store selection ──
  window.selectStore = function(storeId) {
    document.querySelectorAll('.result-item').forEach(item => {
      item.classList.toggle('selected', item.dataset.store === String(storeId));
    });
    document.querySelectorAll('.map-pin').forEach(pin => {
      pin.classList.toggle('selected', pin.id === 'pin' + storeId);
    });
  };

  // ── Use my location ──
  window.useMyLocation = function() {
    const btn = document.querySelector('.use-location-btn');
    btn.textContent = '📍 Locating…';
    btn.disabled = true;
    setTimeout(() => {
      btn.innerHTML = '<span>📍</span> Use my location';
      btn.disabled = false;
    }, 1200);
  };

  // ── Search button ──
  document.getElementById('searchBtn').addEventListener('click', () => {
    const q = searchInput.value.trim();
    if (q) {
      document.getElementById('resultsSubtitle').textContent = `Results for "${q}"`;
    }
  });
</script>
